Bridge Builder:pitch.text:
{
  "pitches": [
    {
      "candidate": "K1",
      "headline": "Automating spirometry trajectory and reference norm reporting for occupational health clients",
      "why": "Pulmoteh d.o.o. needs to automate manual spirometry trend reports for occupational health clients, which currently take twelve minutes per patient. Nebojša Crnković brings expertise in respiratory physiology, longitudinal trajectory modelling, and mixed-effects models from the Faculty of Medicine. His published work on occupational FEV1 decline and spirometric reference equations directly addresses this challenge.",
      "claims": [
        {
          "text": "Pulmoteh d.o.o. faces a challenge where technicians spend about twelve minutes manually creating spirometry trend reports comparing worker data against reference norms.",
          "sources": [
            "C102-CH2"
          ]
        },
        {
          "text": "Nebojša Crnković is an Assistant Professor at the Department of Physiology, Faculty of Medicine, with fields in respiratory physiology and biostatistics.",
          "sources": [
            "R0209"
          ]
        },
        {
          "text": "Crnković has published research on occupational dust exposure and accelerated FEV1 decline in grain elevator workers.",
          "sources": [
            "SYN-PUB-02674"
          ]
        },
        {
          "text": "Crnković has also published work on penalised spline modelling of height-for-age effects on spirometric reference values.",
          "sources": [
            "SYN-PUB-02675"
          ]
        },
        {
          "text": "Crnković provided consultancy services to a regional occupational health service provider, MedWork d.o.o., advising on spirometry.",
          "sources": [
            "R0209"
          ]
        }
      ]
    },
    {
      "candidate": "K4",
      "headline": "Integrating in-season plant sensing data into variable-rate nutrient prescription algorithms",
      "why": "Polje360 d.o.o. builds variable-rate application maps using aging soil data and wants to incorporate current-season plant sensing data into their controllers. Đuro Đorđević from the Faculty of Agriculture specializes in precision agriculture, crop protection modelling, and variable-rate application. His research on drone-acquired canopy reflectance indices provides the exact calibration methods needed for in-season nitrogen status.",
      "claims": [
        {
          "text": "Polje360 d.o.o. builds variable-rate application maps using soil sampling data that is often two to three years old.",
          "sources": [
            "C111-CH2"
          ]
        },
        {
          "text": "Polje360 d.o.o. wants to incorporate current-season plant sensing data so controllers can adjust fertilizer applications dynamically.",
          "sources": [
            "C111-CH2"
          ]
        },
        {
          "text": "Đuro Đorđević is a Senior Research Associate at the Department of Field and Vegetable Crops, Faculty of Agriculture, focusing on precision agriculture and agronomy.",
          "sources": [
            "R0680"
          ]
        },
        {
          "text": "Đorđević published a study on drone-acquired canopy reflectance indices as in-season proxies for crop nitrogen status in winter wheat.",
          "sources": [
            "SYN-PUB-02668"
          ]
        },
        {
          "text": "Đorđević has integrated historical yield maps into phosphorus prescription models in sunflower production.",
          "sources": [
            "SYN-PUB-07652"
          ]
        }
      ]
    },
    {
      "candidate": "K7",
      "headline": "Developing advanced clinical consistency checks to detect nuanced diagnostic and therapeutic coding errors",
      "why": "Kognitiva a.d. processes health insurance claims in bulk, but nuanced clinical inconsistencies slip past their basic rules and cause significant reimbursement losses. Róbert Fehér from the Faculty of Medicine specializes in clinical informatics and health data quality. His published research on rule-based detection of diagnostic-therapeutic inconsistencies directly matches the company's need for advanced error detection.",
      "claims": [
        {
          "text": "Kognitiva a.d. processes bulk health-insurance claims where about 3.2 percent of records contain mismatched diagnosis and procedure codes.",
          "sources": [
            "C110-CH2"
          ]
        },
        {
          "text": "Róbert Fehér is an Assistant Professor at the Department of Internal Medicine, Faculty of Medicine, with expertise in clinical informatics and medical coding.",
          "sources": [
            "R0511"
          ]
        },
        {
          "text": "Fehér published research on rule-based detection of diagnostic-therapeutic inconsistencies in coded hospital records.",
          "sources": [
            "SYN-PUB-06002"
          ]
        },
        {
          "text": "Fehér studied the frequency and pattern of principal diagnosis coding errors in a tertiary hospital in Vojvodina.",
          "sources": [
            "SYN-PUB-06000"
          ]
        },
        {
          "text": "Fehér provided a three-month consulting engagement to a regional hospital software vendor to advise on the design of a coding plausibility module.",
          "sources": [
            "R0511"
          ]
        }
      ]
    }
  ]
}

